async function main() {
  const url = new URL("https://api.aimlapi.com/v2/usage/detail");
  url.searchParams.set("key_prefix", "abcd1234");
  url.searchParams.set("period", "7d");

  const response = await fetch(url, {
    headers: {
      "Authorization": "Bearer <YOUR_AIMLAPI_MANAGEMENT_KEY>",
    },
  });

  const data = await response.json();
  console.log(JSON.stringify(data, null, 2));
}

main();

import requests
import json

def main():
    response = requests.get(
        "https://api.aimlapi.com/v2/usage/detail",
        headers={
            # Insert your AIML API management key instead of <YOUR_AIMLAPI_MANAGEMENT_KEY>:
            "Authorization": "Bearer <YOUR_AIMLAPI_MANAGEMENT_KEY>",
        },
        params={"key_prefix": "abcd1234", "period": "7d"}
    )

    data = response.json()
    print(json.dumps(data, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    main()
